require('dotenv').config();

module.exports = function(RED) {
  const SessionManager = require('kumva-insights/utils/session-manager');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  let globalSessionManager = null;
  const registeredPaths = new Map();

  if (!RED._kumvaWebhookManagers) {
    RED._kumvaWebhookManagers = new Map();
  }
  const webhookManagers = RED._kumvaWebhookManagers;

  async function initializeGlobals() {
    if (!globalSessionManager) {
      const configManager = new ConfigManager();
      globalSessionManager = new SessionManager(configManager.getRedisConfig());
      await globalSessionManager.initialize();
    }
    return { sessionManager: globalSessionManager };
  }

  class WebhookManager {
    constructor() {
      this.nodeRegistry = new Map();
    }
    registerWaitingNode(sessionKey, callback) {
      this.nodeRegistry.set(sessionKey, { callback });
    }
    unregisterWaitingNode(sessionKey) {
      this.nodeRegistry.delete(sessionKey);
    }
    getWaitingNode(sessionKey) {
      return this.nodeRegistry.get(sessionKey);
    }
    parseAfricasTalkingPayload(payload = {}) {
      if (payload.text && payload.from) {
        const identity = payload.from || payload.to || payload.id || payload.messageId;
        return {
          type: 'sms',
          sessionKey: identity ? `sms:${identity}` : null,
          phoneNumber: payload.from,
          content: payload.text,
          linkId: payload.linkId,
          messageId: payload.id,
          sessionIdentity: identity,
          raw: payload
        };
      }
      if (payload.sessionId && (payload.dtmfInput || payload.durationInSeconds || payload.text || payload.callerNumber || payload.from)) {
        const identity = payload.sessionId || payload.callerNumber || payload.from || payload.to || payload.id;
        return {
          type: 'dtmf',
          sessionId: payload.sessionId,
          sessionKey: identity ? `voice:${identity}` : null,
          phoneNumber: payload.callerNumber || payload.from,
          content: payload.dtmfInput || payload.text || '',
          sessionIdentity: identity,
          raw: payload
        };
      }
      return null;
    }
  }

  function registerWebhookEndpoint(webhookPath, webhookManager, flowId, node) {
    if (registeredPaths.has(webhookPath)) {
      throw new Error(`Webhook "${webhookPath}" already registered`);
    }
    registeredPaths.set(webhookPath, flowId);

    if (!RED.httpAdmin._kumvaWebhooks) RED.httpAdmin._kumvaWebhooks = new Map();
    if (RED.httpAdmin._kumvaWebhooks.has(webhookPath)) return;

    RED.httpAdmin._kumvaWebhooks.set(webhookPath, true);

    RED.httpAdmin.post(webhookPath, async (req, res) => {
      try {
        const payload = req.body || {};
        const webhookMgr = webhookManagers.get(flowId) || webhookManager;

        if (!webhookMgr) {
          return res.status(400).json({ success: false, error: 'No manager' });
        }

        const response = webhookMgr.parseAfricasTalkingPayload(payload);
        if (!response) {
          return res.status(400).json({ success: false, error: 'Unable to parse payload' });
        }

        const sessionKey = response.sessionKey || response.sessionId || response.sessionIdentity || response.phoneNumber;
        const { sessionManager } = await initializeGlobals();

        if (!sessionKey) {
          return res.status(400).json({ success: false, error: 'No stable session identity available' });
        }

        const existingSession = await sessionManager.getSession(sessionKey);
        if (!existingSession.exists) {
          await sessionManager.createSession(sessionKey, {
            sessionKey,
            phoneNumber: response.phoneNumber,
            campaignType: response.type === 'dtmf' ? 'voice' : 'sms',
            status: 'active',
            source: 'webhook',
            sessionIdentity: response.sessionIdentity || response.phoneNumber || response.sessionId,
            createdAt: new Date().toISOString(),
            lastUpdated: new Date().toISOString()
          }, 3600);
        }

        const waitingNode = webhookMgr.getWaitingNode(sessionKey);
        if (waitingNode?.callback) {
          setImmediate(() => {
            waitingNode.callback(response);
            webhookMgr.unregisterWaitingNode(sessionKey);
          });
        } else if (node) {
          node.status({ fill: 'green', shape: 'dot', text: 'Webhook received' });
          node.send({
            payload: response.content || '',
            sessionKey,
            phoneNumber: response.phoneNumber,
            webhookPayload: payload,
            response,
            _kumva: { sessionKey, source: 'webhook' }
          });
        }

        res.json({ success: true, sessionKey });
      } catch (error) {
        console.error('[Webhook] Error:', error);
        res.status(500).json({ success: false, error: error.message });
      }
    });
  }

  function KumvaStartCampaignNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const flowId = this.z || this.id;

    const initiationMode = config.initiationMode || 'outbound';
    const campaignType = config.campaignType || 'sms';
    const webhookPath = config.webhookPath || '/kumva/webhook';
    const baseUrl = process.env.KUMVA_WEBHOOK_BASE_URL || 'http://localhost:1880';
    const webhookUrl = baseUrl.replace(/\/$/, '') + webhookPath;
    const webhookManager = new WebhookManager();

    webhookManagers.set(flowId, webhookManager);

    try {
      registerWebhookEndpoint(webhookPath, webhookManager, flowId, node);
      node.status({ fill: 'blue', shape: 'dot', text: `Listening: ${webhookPath}` });
    } catch (error) {
      node.error(error.message);
      node.status({ fill: 'red', shape: 'ring', text: 'Webhook error' });
      return;
    }

    initializeGlobals().catch(e => node.error(e.message));

    node.on('input', async function(msg) {
      try {
        const phoneNumber = msg.phoneNumber || msg.contactData?.phone || msg.contactData?.[config.phoneColumn || 'phone'];
        const campaignId = msg.campaignId || `campaign_${Date.now()}`;

        if (!phoneNumber || !campaignId) {
          return node.error('Missing phoneNumber or campaignId');
        }

        const campaignData = {
          campaignId,
          phoneNumber,
          campaignType,
          initiationMode,
          contactData: msg.contactData || {},
          initialMessage: msg.initialMessage || '',
          webhookUrl,
          credentials: {
            username: node.credentials?.username,
            apiKey: node.credentials?.apiKey
          },
          shortCode: config.shortCode || null,
          callerId: config.callerId || null,
          sessionTimeout: helpers.timeToSeconds(config.sessionTimeout || '3600s')
        };

        const outputMsg = {
          ...msg,
          campaignId,
          phoneNumber,
          campaignData,
          initiationMode,
          credentials: campaignData.credentials,
          webhookUrl,
          _kumva: {
            campaignId,
            webhookUrl,
            mode: initiationMode
          }
        };

        node.status({ fill: 'green', shape: 'dot', text: 'Context ready' });
        node.send(outputMsg);
      } catch (error) {
        node.error(`StartCampaign: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
      }
    });

    node.on('close', (done) => {
      webhookManagers.delete(flowId);
      registeredPaths.delete(webhookPath);
      done();
    });
  }

  RED.httpAdmin.get('/kumva/webhook/validate/:path', (req, res) => {
    const path = '/' + req.params.path;
    res.json({ available: !registeredPaths.has(path) });
  });

  RED.nodes.registerType('kumva-start-campaign', KumvaStartCampaignNode, {
    credentials: {
      username: { type: 'text' },
      apiKey: { type: 'password' }
    }
  });
};